from itertools import product
from sympy import Matrix, ZZ
from sympy.matrices.normalforms import smith_normal_form


def parts_in_box(r,q):
    out=[]
    def rec(prev,k,cur):
        if k==r:
            out.append(tuple(x for x in cur if x))
            return
        for x in range(min(prev,q),-1,-1):
            rec(x,k+1,cur+[x])
    rec(q,0,[])
    return out

def contains(nu,mu):
    return all((nu[k] if k<len(nu) else 0) >= x for k,x in enumerate(mu))

def size(p): return sum(p)

def lr_coeff(lam,mu,nu):
    # LR tableaux of skew shape nu/mu, content lam, read right-to-left by rows.
    if size(lam)+size(mu)!=size(nu) or not contains(nu,mu): return 0
    cells=[]
    for rr in range(len(nu)):
        m=mu[rr] if rr<len(mu) else 0
        for cc in range(nu[rr],m,-1):
            cells.append((rr,cc))
    vals={}; used=[0]*(len(lam)+1); ans=0
    def go(t):
        nonlocal ans
        if t==len(cells):
            ans+=1; return
        rr,cc=cells[t]
        right=vals.get((rr,cc+1))
        above=vals.get((rr-1,cc))
        for x in range(1,len(lam)+1):
            if used[x]>=lam[x-1]: continue
            if right is not None and x>right: continue
            if above is not None and above>=x: continue
            used[x]+=1
            if x==1 or used[x] <= used[x-1]:
                vals[(rr,cc)]=x; go(t+1); del vals[(rr,cc)]
            used[x]-=1
    go(0)
    return ans

def compute(r,q,i,j):
    B=parts_in_box(r,q)
    rho=tuple([i]*j)
    U=[p for p in B if contains(p,rho)]
    index={p:k for k,p in enumerate(U)}
    rel=[]
    for lam in B:
        if not lam: continue
        for mu in U:
            row=[0]*len(U)
            for nu in U:
                c=lr_coeff(lam,mu,nu)
                row[index[nu]]=c
            if any(row): rel.append(row)
    M=Matrix(rel)
    D=smith_normal_form(M,domain=ZZ)
    diagonal=[abs(D[k,k]) for k in range(min(D.rows,D.cols)) if D[k,k]!=0]
    rank=len(diagonal)
    free=len(U)-rank
    torsion=[int(x) for x in diagonal if x!=1]
    # proposed families, recorded as partitions bounded by the stated upper shapes
    a=min(q-i,r-j); b=min(i,j)
    upper1=tuple([i+a]*b+[i]*(j-b))
    upper2=tuple([i]*j+[b]*a)
    fam1=[p for p in U if contains(upper1,p)]
    fam2=[p for p in U if contains(upper2,p)]
    return dict(r=r,q=q,i=i,j=j,U=len(U),relations=len(rel),rank=rank,free=free,torsion=torsion,a=a,b=b,N_expected=__import__('math').comb(a+b,a),family1=len(fam1),family2=len(fam2),diagonal=[int(x) for x in diagonal])

results=[compute(2,6,1,1),compute(5,2,1,1)]
for x in results: print(x)
